import{_ as e,o as d,c as n,a6 as s}from"./chunks/framework.DtfPIzdJ.js";const h=JSON.parse('{"title":"Error codes","description":"","frontmatter":{},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md"}'),r={name:"reference/errors.md"};function o(a,t,i,p,c,l){return d(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h1><p>Run <code>cluub errors CODE</code> in a terminal for the same information.</p><table tabindex="0"><thead><tr><th>Code</th><th>Problem</th><th>How to fix</th></tr></thead><tbody><tr><td><span id="e001"><strong>E001</strong></span></td><td>Tabs used for indentation</td><td>Indent with 2 spaces.</td></tr><tr><td><span id="e002"><strong>E002</strong></span></td><td>Indentation step is not 2 spaces</td><td>Indent each nested block by exactly 2 spaces.</td></tr><tr><td><span id="e003"><strong>E003</strong></span></td><td>Indentation does not line up with an outer block</td><td>Line up the line with an outer block.</td></tr><tr><td><span id="e004"><strong>E004</strong></span></td><td>Unterminated text</td><td>Close the text with &quot;. Use triple quotes for multiple lines.</td></tr><tr><td><span id="e005"><strong>E005</strong></span></td><td>Unexpected character</td><td>Remove the character. Text uses double quotes.</td></tr><tr><td><span id="e006"><strong>E006</strong></span></td><td>Symbol operator used where Cluub uses a word</td><td>Use is, is not, and, or, not.</td></tr><tr><td><span id="e010"><strong>E010</strong></span></td><td>Unexpected token / syntax error</td><td>Read the message: it says what was expected and what was found.</td></tr><tr><td><span id="e011"><strong>E011</strong></span></td><td>Unknown top-level declaration</td><td>A file contains declarations: model, store, client, service, api, page, component, layout, test, app.</td></tr><tr><td><span id="e012"><strong>E012</strong></span></td><td>Unknown member inside a declaration</td><td>Each declaration kind allows specific members; the hint lists them.</td></tr><tr><td><span id="e013"><strong>E013</strong></span></td><td>Unknown view element</td><td>Use a known element, or a Capitalized component name.</td></tr><tr><td><span id="e101"><strong>E101</strong></span></td><td>Duplicate declaration</td><td>Rename one of the declarations.</td></tr><tr><td><span id="e102"><strong>E102</strong></span></td><td>Declaration name must be PascalCase</td><td>Rename to PascalCase.</td></tr><tr><td><span id="e103"><strong>E103</strong></span></td><td>Field, action, state or parameter name must be camelCase</td><td>Rename to camelCase.</td></tr><tr><td><span id="e104"><strong>E104</strong></span></td><td>Unknown dependency in <code>uses</code></td><td>Fix the spelling, or declare the dependency.</td></tr><tr><td><span id="e105"><strong>E105</strong></span></td><td>Unknown name</td><td>Fix the spelling, or create the value with let.</td></tr><tr><td><span id="e106"><strong>E106</strong></span></td><td>Dependency used without <code>uses</code></td><td>Add uses X to the declaration.</td></tr><tr><td><span id="e107"><strong>E107</strong></span></td><td>Unknown action, route or store method</td><td>Use an existing action/route/method; the hint lists them.</td></tr><tr><td><span id="e108"><strong>E108</strong></span></td><td>Wrong arguments in a call</td><td>Match the parameter names and count.</td></tr><tr><td><span id="e109"><strong>E109</strong></span></td><td>Unknown model field</td><td>Use a field that exists on the model.</td></tr><tr><td><span id="e110"><strong>E110</strong></span></td><td>Assignment to a name that was never created</td><td>Create it first with let (or state on a page).</td></tr><tr><td><span id="e111"><strong>E111</strong></span></td><td>Name created twice in the same block</td><td>Use name = value to change an existing value.</td></tr><tr><td><span id="e112"><strong>E112</strong></span></td><td><code>input</code>/<code>checkbox</code> must be bound to state</td><td>Declare page state and bind the input to it.</td></tr><tr><td><span id="e113"><strong>E113</strong></span></td><td>Event handler must be an action call</td><td>Events call actions: on click save or on click remove(item.id).</td></tr><tr><td><span id="e114"><strong>E114</strong></span></td><td>Wrong component properties</td><td>Pass the properties the component takes.</td></tr><tr><td><span id="e115"><strong>E115</strong></span></td><td>Duplicate route or action name</td><td>Rename the duplicate.</td></tr><tr><td><span id="e116"><strong>E116</strong></span></td><td>Unknown layout</td><td>Declare the layout or fix its name.</td></tr><tr><td><span id="e117"><strong>E117</strong></span></td><td>Api or action called while a view is drawn</td><td>Views only show data. Load it into <code>state</code> in <code>when loaded</code> or an action, then show the state.</td></tr><tr><td><span id="e120"><strong>E120</strong></span></td><td>Test-only statement used outside a test</td><td>Move the statement into a test.</td></tr><tr><td><span id="e201"><strong>E201</strong></span></td><td>Layer rule violated</td><td>Follow page → api → service → store/client.</td></tr><tr><td><span id="e202"><strong>E202</strong></span></td><td>Circular dependency between services</td><td>Move shared logic into a third service.</td></tr><tr><td><span id="e203"><strong>E203</strong></span></td><td>Components and layouts cannot use dependencies</td><td>Pass data to components with takes.</td></tr><tr><td><span id="e204"><strong>E204</strong></span></td><td>AI called from the UI layer</td><td>Call AI from a service and expose it through an api.</td></tr><tr><td><span id="e205"><strong>E205</strong></span></td><td>Environment secret read from the UI layer</td><td>Read env in a service; send only what the page needs.</td></tr><tr><td><span id="e301"><strong>E301</strong></span></td><td>Declaration is in the wrong folder</td><td>Move the file to the folder for its kind.</td></tr><tr><td><span id="e401"><strong>E401</strong></span></td><td>Hard-coded secret detected</td><td>Move the secret to .env and read env.NAME.</td></tr><tr><td><span id="w101"><strong>W101</strong></span></td><td>Unused dependency</td><td>Remove the unused dependency.</td></tr><tr><td><span id="w102"><strong>W102</strong></span></td><td>Action is too long (Single Responsibility)</td><td>Split the action into smaller ones.</td></tr><tr><td><span id="w103"><strong>W103</strong></span></td><td>Service has too many actions (Single Responsibility / Interface Segregation)</td><td>Split the service by responsibility.</td></tr><tr><td><span id="w104"><strong>W104</strong></span></td><td>Missing <code>about</code> description</td><td>Add an about line.</td></tr><tr><td><span id="w105"><strong>W105</strong></span></td><td>State is never used</td><td>Remove the unused state or show it.</td></tr><tr><td><span id="w106"><strong>W106</strong></span></td><td>Page has no view</td><td>Add a view block.</td></tr><tr><td><span id="w107"><strong>W107</strong></span></td><td>Layout without exactly one slot</td><td>Put one <code>slot</code> where the page should appear. With none the page is hidden; with two it appears twice.</td></tr><tr><td><span id="w108"><strong>W108</strong></span></td><td>Unknown app setting</td><td>Use one of <code>about</code>, <code>port</code>, <code>ai</code>, <code>aiModel</code>; other settings are ignored.</td></tr></tbody></table><p>Codes starting with <strong>E</strong> are errors (the build stops). <strong>W</strong> codes are warnings. Suggestions use W104.</p>',4)])])}const m=e(r,[["render",o]]);export{h as __pageData,m as default};
